      font-size: 18px;
      font-weight: 600;
      line-height: 24px;
      display: flex;
      align-items: center;
      margin-bottom: 5px;
      cursor: pointer;
      img{
        width: 16px;
        height: 16px;
        margin-right: 3px;
      }
    }
  }
  .mainm{
    width: 100%;
    display: flex;
    justify-content: space-between;
    margin-top: 12px;

    .mainm_l{
      width: 25%;
      .mainm_tt{
        position: relative;

        // .mainm_ttr{
        //   position: absolute;
