      }
    }
    .mainm_c{
      width: 48%;
    }
    .mainm_r{
      width: 25%;
    }
  }
  .wei_line{
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;

    .wei_line_l{
      font-size: 14px;
      display: flex;
      align-items: center;
      font-weight: 500;
      color: #192C7D;
    }
    .wei_line_r{
      ::v-deep .el-select .el-input__inner{
        border-radius: 20px;
        background: #DDDEFF;
        color: #0750cf;
      }
      ::v-deep .el-select .el-input .el-select__caret{
        color: #0750cf;
      }
      .tab_btns{
        display: flex;


        .tab_btns_item{
          margin-left: 8px;
          font-size: 12px;
          color: #405466;
          background: #FBFBFD;
          border-radius: 8px;
          font-weight: 600;
          padding: 6px 8px;
          cursor: pointer;
        }
        .tab_btns_item_active{
          background: #192C7D;
          color: #fff;
        }
      }
    }
    .fang{
      width: 6px;
      height: 6px;
      background: #9EC2FF;
      margin-right: 5px;
    }
