    // background: linear-gradient(88deg,#bcd7fe  0%, #E6F0FE 100%);#bcd7fe
    box-shadow: 0px 2px 8px 0px rgba(1,51,100,0.04);
    border-radius: 8px;
    margin-top: 10px;
    // border: 1px solid #333;
    padding: 10px 10px;
    box-sizing: border-box;
  }




