        line-height: 30px;
        padding: 0 15px;
        background: #192C7D;
        color: #fff;
        border-radius: 8px;
        margin-right: 5px;
      }
      .navv_item{
        width: 40px;
        height: 30px;
        line-height: 30px;
        background: #FBFBFD;
        border-radius: 8px;
        margin-right: 5px;
