      height: 245px;
    }
    .mainm_cb_r{
      width: 49%;
      height: 245px;
    }
    .mainm_cb_c{
      width: 100%;
      height: 225px;
    }
    .kuai{
      margin-top: 0 !important;
    }
    .kuai2{
      border-radius: 6px;
      box-shadow: 1px 2px 10px #ccc;
    }
  }


}

